const remapQuickReplyReactions = `-- name: RemapQuickReplyReactions :execrows
UPDATE campaign_recipients SET
    reaction = CASE WHEN ($1::jsonb ->> reply_payload) IN ('positive', 'negative', 'neutral') THEN $1::jsonb ->> reply_payload END,
    reaction_source = CASE WHEN ($1::jsonb ->> reply_payload) IN ('positive', 'negative', 'neutral') THEN 'quick_reply' END,
    reaction_at = CASE WHEN ($1::jsonb ->> reply_payload) IN ('positive', 'negative', 'neutral') THEN coalesce(reaction_at, replied_at, now()) END,
    updated_at = now()
WHERE campaign_id = $2 AND reply_payload IS NOT NULL AND reaction_source IS DISTINCT FROM 'manual'
  AND reaction IS DISTINCT FROM CASE WHEN ($1::jsonb ->> reply_payload) IN ('positive', 'negative', 'neutral') THEN $1::jsonb ->> reply_payload END
`

type RemapQuickReplyReactionsParams struct {
	ReactionMap []byte
	CampaignID  uuid.UUID
}

// After the mapping changed: recipients who tapped a quick reply take its
// label (none when unmapped); AI labels give way, manual ones stay.
func (q *Queries) RemapQuickReplyReactions(ctx context.Context, arg RemapQuickReplyReactionsParams) (int64, error) {
	result, err := q.db.Exec(ctx, remapQuickReplyReactions, arg.ReactionMap, arg.CampaignID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

