const spamWindow = `-- name: SpamWindow :one
SELECT count(*)::bigint AS attempts,
    count(*) FILTER (WHERE w.error_code IN ('131049', '131050'))::bigint AS ecosystem,
    count(*) FILTER (WHERE w.opted_out_at IS NOT NULL)::bigint AS opted_out
FROM (SELECT r.error_code, r.opted_out_at FROM campaign_recipients r
      WHERE r.campaign_id = $1 AND r.attempted_at IS NOT NULL
        AND ($2::timestamptz IS NULL OR r.attempted_at > $2::timestamptz)
      ORDER BY r.attempted_at DESC LIMIT $3) w
`

type SpamWindowParams struct {
	CampaignID uuid.UUID
	Since      *time.Time
	N          int32
}

type SpamWindowRow struct {
	Attempts  int64
	Ecosystem int64
	OptedOut  int64
}

// The campaign's last n attempts (recipients whose message reached Meta)
// and how many of them hit 131049/131050 or opted out.
func (q *Queries) SpamWindow(ctx context.Context, arg SpamWindowParams) (SpamWindowRow, error) {
	row := q.db.QueryRow(ctx, spamWindow, arg.CampaignID, arg.Since, arg.N)
	var i SpamWindowRow
	err := row.Scan(&i.Attempts, &i.Ecosystem, &i.OptedOut)
	return i, err
}

const staleCampaignExports = `-- name: StaleCampaignExports :many
SELECT id FROM campaign_exports WHERE status IN ('queued', 'running') AND created_at < now() - interval '30 minutes'
`

// Exports whose job was lost (queued or running for long).
func (q *Queries) StaleCampaignExports(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, staleCampaignExports)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
